def strongPasswordChecker(password: str) -> int:
    n = len(password)
    has_lower = any(c.islower() for c in password)
    has_upper = any(c.isupper() for c in password)
    has_digit = any(c.isdigit() for c in password)
    missing_types = (0 if has_lower else 1) + (0 if has_upper else 1) + (0 if has_digit else 1)
    if n < 6:
        return max(6 - n, missing_types)
    # Count runs of length >= 3
    repeats = []
    i = 2
    while i < n:
        if password[i] == password[i - 1] == password[i - 2]:
            length = 2
            while i < n and password[i] == password[i - 1]:
                length += 1
                i += 1
            repeats.append(length)
        else:
            i += 1
    if n <= 20:
        replace_needed = sum(k // 3 for k in repeats)
        return max(replace_needed, missing_types)
    # n > 20: prioritize deletions
    delete_needed = n - 20
    rem_delete = delete_needed
    # Prioritize modulo 0 runs (save 1 replace with 1 delete)
    for mod in range(3):
        for idx in range(len(repeats)):
            if repeats[idx] >= 3 and repeats[idx] % 3 == mod:
                cost = mod + 1
                if rem_delete >= cost:
                    rem_delete -= cost
                    repeats[idx] -= cost
    replace_needed = sum(max(0, k // 3) for k in repeats)
    if rem_delete > 0:
        replace_needed -= rem_delete // 3
    return delete_needed + max(replace_needed, missing_types)

